#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
static int bk7258_ap_validate_secondary_bootstrap(void)
{
  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
    bk7258_cpu2_probe_state();
#ifdef CONFIG_BK7258_AP_IPI
  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
#endif
#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
#endif
  __asm volatile ("dmb sy" ::: "memory");

  if (cpu2->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
      cpu2->version != BK7258_CPU2_PROBE_STATE_VERSION ||
      cpu2->size != sizeof(struct bk7258_cpu2_probe_state_s) ||
      cpu2->generation != bk7258_ap_boot_state()->generation ||
      cpu2->state != BK7258_CPU2_EXPECTED_STATE ||
      cpu2->error != BK7258_CPU2_PROBE_ERROR_NONE ||
      cpu2->secondary_ready != 1 ||
      cpu2->online_mask != BK7258_CPU2_EXPECTED_MASK ||
      cpu2->local_core_id != 1 ||
      cpu2->physical_core_id != 2 ||
      cpu2->runtime_vtor != cpu2->vector ||
      cpu2->runtime_msp <= BK7258_CPU2_BOOT_STACK_BASE ||
          platform.first_error_stage == BK7258_AP_STAGE_PSRAM)
        {
          platform_error = BK7258_AP_ERROR_PSRAM;
        }

      return bk7258_ap_startup_failed(failure, platform_error, ret);
    }

#ifdef CONFIG_BK7258_PSRAM
#ifdef CONFIG_BK7258_PSRAM_SYSTEM_HEAP
  /* Preserve the baseline boundary: AP validates its boot contract before
   * donating a region from the already initialized private PSRAM heap to the
   * NuttX system heap.
   */

  ret = bk7258_psram_add_system_heap(
    CONFIG_BK7258_PSRAM_SYSTEM_HEAP_SIZE);
  if (ret < 0)
    {
      return bk7258_ap_startup_failed(
               failure, BK7258_AP_ERROR_PSRAM, ret);
    }
#ifdef CONFIG_BK7258_PSRAM_EXT_SYSTEM_HEAP
  ret = bk7258_psram_add_extended_system_heap();
  if (ret < 0)
    {
      return bk7258_ap_startup_failed(
               failure, BK7258_AP_ERROR_PSRAM, ret);
    }

  syslog(LOG_NOTICE, "BPSR AP SYSTEM HEAP base=%08lx size=%lu\n",
         (unsigned long)BK7258_PSRAM_AP_EXT_HEAP_BASE,
         (unsigned long)CONFIG_BK7258_PSRAM_EXT_SYSTEM_HEAP_SIZE);
#endif
#endif

  state->reserved[BK7258_PSRAM_AP_RESERVED_HEAP] =
    BK7258_PSRAM_AP_HEAP_BASE;
  state->reserved[BK7258_PSRAM_AP_RESERVED_GATE] =
    BK7258_PSRAM_AP_HEAP_READY;
#ifdef CONFIG_BK7258_PSRAM_TEST

void bk7258_psram_free(void *ptr)
{
  irqstate_t flags;

  if (ptr == NULL)
    {
      return;
    }

  if (bk7258_psram_ready() && bk7258_psram_heap_contains(ptr))
    {
      flags = spin_lock_irqsave(&g_bk7258_psram_lock);
      mm_free(g_bk7258_psram_heap, ptr);
      spin_unlock_irqrestore(&g_bk7258_psram_lock, flags);
    }
}

int bk7258_psram_add_system_heap(size_t size)
{
  void *memory;

  if (!bk7258_psram_ready() || size == 0 ||
      size >= BK7258_PSRAM_LOCAL_HEAP_SIZE)
    {
      return -EINVAL;
    }

  if (g_bk7258_psram_system_heap != NULL)
    {
      return g_bk7258_psram_system_heap_size == size ? OK : -EALREADY;
    }

  memory = bk7258_psram_malloc(size);
  if (memory == NULL)
    {
      return -ENOMEM;
    }

  /* The private PSRAM heap keeps the enclosing block allocated permanently.
   * NuttX may then safely manage allocations inside it as a second region;
   * the two allocators never see overlapping free space.  The NuttX heap
   * control block and lock remain in exclusive-store-capable internal SRAM.
   */

  kumm_addregion(memory, size);
  g_bk7258_psram_system_heap = memory;
  g_bk7258_psram_system_heap_size = size;
  return OK;
}

#ifdef CONFIG_BK7258_PSRAM_EXT_SYSTEM_HEAP
int bk7258_psram_add_extended_system_heap(void)
{
  if (!bk7258_psram_ready() || !bk7258_psram_mpu_valid())
    {
      return -ENODEV;
    }

  if (g_bk7258_psram_info.capacity != BK7258_PSRAM_16M_SIZE)
    {
      return -ENOSPC;
    }

  if (!g_bk7258_psram_extended_heap)
    {
      /* CP validated capacity and aliasing before AP release. No SDK slab
       * or private allocator owns this bank. Keep the NuttX heap metadata
       * and its SMP lock in SRAM, as for the original system region.
       */

      kumm_addregion((void *)BK7258_PSRAM_AP_EXT_HEAP_BASE,
                     CONFIG_BK7258_PSRAM_EXT_SYSTEM_HEAP_SIZE);
      g_bk7258_psram_extended_heap = true;
    }

  return OK;
}
#endif

#ifdef CONFIG_BK7258_PSRAM_MEDIA
config BK7258_PSRAM_SYSTEM_HEAP
	bool "Add reserved role-local PSRAM to the NuttX system heap"
	default n
	depends on BK7258_PSRAM
	depends on MM_REGIONS > 1
	help
		Reserve one block from the current role's private PSRAM allocator and
		add that block as a second NuttX system-heap region.  The role-local
		PSRAM allocator retains ownership of the enclosing block, while NuttX
		manages task stacks and ordinary allocations inside it.  Select a size
		that fits the role's partition: CP owns 128 KiB and AP owns 640 KiB in
		the default 8 MiB layout.  This is useful for test or application
		profiles whose thread stacks do not fit in internal SRAM.

config BK7258_PSRAM_SYSTEM_HEAP_SIZE
	hex "Role-local PSRAM system-heap region size"
	default 0x50000 if BK7258_AP_CORE
	default 0x10000 if !BK7258_AP_CORE
	range 0x10000 0x80000 if BK7258_AP_CORE
	range 0x10000 0x1f000 if !BK7258_AP_CORE
	depends on BK7258_PSRAM_SYSTEM_HEAP

config BK7258_PSRAM_EXT_SYSTEM_HEAP
	bool "Use the high PSRAM bank for the AP system heap"
	default n
	depends on BK7258_AP_CORE && BK7258_PSRAM_SYSTEM_HEAP
	depends on MM_REGIONS > 2
	help
		Donate a separate region above the SDK's fixed low 8 MiB layout to
		the NuttX allocator. CP must publish a detected, non-aliased 16 MiB
		capacity for this boot generation. A smaller or unknown part fails
		AP startup instead of aliasing SDK media or CP storage.

config BK7258_PSRAM_EXT_SYSTEM_HEAP_SIZE
	hex "AP high-bank system heap size"
	default 0x400000
	range 0x100000 0x800000
	depends on BK7258_PSRAM_EXT_SYSTEM_HEAP

config BK7258_SDK_SRAM_HEAP
	bool "Reserve internal SRAM for SDK SRAM-only allocations"
	default n
	depends on BK7258_PSRAM_SYSTEM_HEAP
	help
		Reserve an internal-SRAM heap for SDK allocation APIs whose public
		contract requires SRAM.  A NuttX system heap extended with PSRAM may
		otherwise return a PSRAM address from os_sram_malloc(), which is not
		valid for Wi-Fi pbufs and hardware descriptors.  The selected board
		profile must budget the reserve against another internal-SRAM user.

config BK7258_SDK_SRAM_HEAP_SIZE
	hex "SDK SRAM-only heap size"
	default 0x4000
	range 0x1000 0x10000
	depends on BK7258_SDK_SRAM_HEAP

