static inline_function
void rspin_lock(FAR rspinlock_t *lock)
{
  rspinlock_t new_val;
  rspinlock_t old_val;
  int         cpu = this_cpu() + 1;

  /* Already owned this lock. */

  old_val.val = atomic_read(&lock->val);

  if (old_val.owner == cpu)
    {
      lock->count += 1;
