{
  uint32_t magic;
  uint32_t version;
  uint32_t size;
  uint32_t generation;     /* gate used by dispatch() */
  uint32_t command;
  uint32_t state;          /* checked against BK7258_AP_STATE_READY */
  uint32_t error;
  uint32_t last_event;
  uint32_t reserved[32];
};

