void bk7258_system_reset(enum bk7258_reset_source_e source)
{
#ifdef CONFIG_BK7258_AP_SUPERVISOR
  assert(source == BK7258_RESET_SOURCE_REBOOT);
  g_reset_calls++;
  longjmp(g_reset_env, 1);
#else
  (void)source;
  abort();
#endif
}

